by", "node": "LIM:insufficient_exposure"}, {"rel": "auto_has_risk", "node": "RISK:EXPOSURE_SPARSITY"}]}, {"id": "FAM:SF-APPS-012", "label": "Study family SF-APPS-012: Defensive PPP allowed and possession share, RS vs playoffs", "score": 0.189, "reached_via": ["request matches RQC:RQC-049 (0.30); FAM:SF-APPS-012 auto_addresses_question RQC:RQC-049"], "attributes": {"observed_research_question": "Defensive PPP allowed and possession share, RS vs playoffs", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Playoff defenses suppress DRIVE more than RS defenses (both lower PPP allowed and lower share).", "observed_result": "DRIVE allowed 1.191 -> 0.923 (-0.268), share 21.2% -> 18.2%; PNR -0.139, share +12.1pp; PULL_UP +0.341, share -7.6pp.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No inferential test; PNR share jump of +12.1pp may reflect tagging differences.", "observed_sample_and_power": "25 teams", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "25 defensive teams, min 30 poss per cell; RS vs playoff PPP allowed and opponent possession share by PT.", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}], "n_results": 4}

